<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { DeleteOutlined, EditOutlined, PlusOutlined, ReloadOutlined, SaveOutlined, ThunderboltOutlined } from '@ant-design/icons-vue'; import { message, Modal } from 'ant-design-vue'; import { aiApi, aiDataSourceApi, monitoredUsersApi, tweetsApi } from '@/services/api'; import { getErrorMessage } from '@/services/http'; import type { AiDataSourceStatus, AiJob, AiSettings, AiSkill, AiSkillPayload, AiUserProfile, AiUserSkillBinding, EntityId, MonitoredUser, Tweet, UpdateAiSettingsPayload } from '@/types'; import MetricCard from '@/components/MetricCard.vue'; import PageHeader from '@/components/PageHeader.vue'; import StatusPill from '@/components/StatusPill.vue'
const route = useRoute(); const tab = ref(typeof route.query.tab === 'string' ? route.query.tab : 'jobs'); const draftOpen = ref(false); const draftSaving = ref(false); const binding = ref<AiUserSkillBinding | null>(null); const bindingIds = ref<EntityId[]>([]); const bindingLoading = ref(false); const draftForm = reactive({ id: 0 as EntityId, title: '', content: '', excerpt: '', revision: 0 }); const loading=reactive({jobs:false,settings:false,skills:false,source:false}); const jobs=ref<AiJob[]>([]); const jobsTotal=ref(0); const skills=ref<AiSkill[]>([]); const settings=ref<AiSettings|null>(null); const source=ref<AiDataSourceStatus|null>(null); const users=ref<MonitoredUser[]>([]); const tweets=ref<Tweet[]>([]); const profile=ref<AiUserProfile|null>(null); const filters=reactive({page:1,page_size:15,status:'all'}); const skillOpen=ref(false); const sourceModels=ref<string[]>([]); const editingSkill=ref<AiSkill|null>(null); const skillForm=reactive<AiSkillPayload>({name:'',description:'',instructions:'',is_active:true}); const settingsForm=reactive<UpdateAiSettingsPayload>({enabled:false,auto_generate:true,prompt_template:'',language:'zh-CN',tone:'专业自然',reasoning_effort:'medium',default_skill_ids:[],max_attempts:3,max_output_tokens:2500,request_timeout_seconds:60}); const sourceForm=reactive({name:'OpenAI',base_url:'https://api.openai.com/v1',model:'gpt-5.6-terra',api_key:''}); const selectedUser=ref(''); const feature=ref('article_generation')
const running = computed(() => jobs.value.filter((job) => ['queued','running','retry_wait'].includes(job.status)).length)
function applySettings(value:AiSettings){settings.value=value;Object.assign(settingsForm,{enabled:value.enabled,auto_generate:value.auto_generate,prompt_template:value.prompt_template||'',language:value.language,tone:value.tone,reasoning_effort:value.reasoning_effort,default_skill_ids:[...(value.default_skill_ids||[])],max_attempts:value.max_attempts,max_output_tokens:value.max_output_tokens,request_timeout_seconds:value.request_timeout_seconds})}
async function loadJobs(){loading.jobs=true;try{const result=await aiApi.jobs({page:filters.page,page_size:filters.page_size,status:filters.status==='all'?undefined:filters.status});jobs.value=result.items;jobsTotal.value=result.total}catch(e){message.error(getErrorMessage(e,'无法加载 AI 任务'))}finally{loading.jobs=false}}
async function loadSettings(){loading.settings=true;try{applySettings(await aiApi.settings())}catch(e){message.error(getErrorMessage(e,'无法加载 AI 设置'))}finally{loading.settings=false}}
async function loadSkills(){loading.skills=true;try{skills.value=await aiApi.skills()}catch(e){message.error(getErrorMessage(e,'无法加载 Skills'))}finally{loading.skills=false}}
async function loadSource(){loading.source=true;try{source.value=await aiDataSourceApi.status();if(source.value.configured){sourceForm.name=source.value.name||'OpenAI';sourceForm.base_url=source.value.base_url||'';sourceForm.model=source.value.model||''}}catch(e){message.error(getErrorMessage(e,'无法加载 AI 数据源'))}finally{loading.source=false}}
async function saveSource(){if(!sourceForm.name||!sourceForm.base_url||!sourceForm.model)return message.warning('请填写名称、Base URL 和模型');try{source.value=await aiDataSourceApi.save({...sourceForm,protocol:'openai_responses'});sourceForm.api_key='';message.success('AI 数据源已加密保存')}catch(e){message.error(getErrorMessage(e,'保存失败'))}}
async function testSource(){try{const result=await aiDataSourceApi.test();sourceModels.value=result.models;result.valid?message.success(result.message):message.warning(result.message);await loadSource()}catch(e){message.error(getErrorMessage(e,'测试失败'))}}
async function saveSettings(){loading.settings=true;try{applySettings(await aiApi.updateSettings({...settingsForm,default_skill_ids:[...settingsForm.default_skill_ids]}));message.success('AI 配置已保存')}catch(e){message.error(getErrorMessage(e,'保存失败'))}finally{loading.settings=false}}
function editSkill(skill?:AiSkill){editingSkill.value=skill||null;Object.assign(skillForm,skill?{name:skill.name,description:skill.description||'',instructions:skill.instructions,is_active:skill.is_active}:{name:'',description:'',instructions:'',is_active:true});skillOpen.value=true}
async function saveSkill(){if(!skillForm.name.trim()||!skillForm.instructions.trim())return message.warning('请填写名称和 Skill 指令');try{editingSkill.value?await aiApi.updateSkill(editingSkill.value.id,skillForm):await aiApi.createSkill(skillForm);skillOpen.value=false;await loadSkills();message.success('Skill 已保存')}catch(e){message.error(getErrorMessage(e,'保存 Skill 失败'))}}
function removeSkill(skill:AiSkill){Modal.confirm({title:`删除 Skill「${skill.name}」？`,okType:'danger',okText:'删除',cancelText:'取消',onOk:async()=>{await aiApi.removeSkill(skill.id);await loadSkills();message.success('Skill 已删除')}})}
async function retry(job:AiJob){try{await aiApi.retryJob(job.id);await loadJobs();message.success('任务已重新排队')}catch(e){message.error(getErrorMessage(e,'重试失败'))}}
async function removeJob(job:AiJob){Modal.confirm({title:'删除这条 AI 任务？',okType:'danger',okText:'删除',cancelText:'取消',onOk:async()=>{await aiApi.removeJob(job.id);await loadJobs();message.success('任务已删除')}})}
function editDraft(job: AiJob) { if (!job.draft) return; Object.assign(draftForm, { id: job.draft.id, title: job.draft.title, content: job.draft.content, excerpt: job.draft.excerpt || '', revision: job.draft.revision }); draftOpen.value = true }
async function saveDraft() { draftSaving.value = true; try { await aiApi.updateDraft(draftForm.id, { title: draftForm.title.trim(), content: draftForm.content.trim(), excerpt: draftForm.excerpt.trim(), revision: draftForm.revision }); draftOpen.value = false; await loadJobs(); message.success('草稿已保存') } catch (e) { message.error(getErrorMessage(e, '草稿保存失败')) } finally { draftSaving.value = false } }
async function loadContext(){if(!selectedUser.value)return;bindingLoading.value=true;try{[profile.value,binding.value]=await Promise.all([aiApi.userProfile(selectedUser.value),aiApi.userSkillBinding(selectedUser.value,feature.value)]);bindingIds.value=[...(binding.value?.skill_ids||[])]}catch(e){message.error(getErrorMessage(e,'读取用户上下文失败'))}finally{bindingLoading.value=false}}
async function saveBinding(){if(!selectedUser.value)return;bindingLoading.value=true;try{binding.value=await aiApi.saveUserSkillBinding(selectedUser.value,feature.value,bindingIds.value);message.success('Skill 绑定已保存')}catch(e){message.error(getErrorMessage(e,'保存 Skill 绑定失败'))}finally{bindingLoading.value=false}}
onMounted(async()=>{await Promise.all([loadJobs(),loadSettings(),loadSkills(),loadSource()]);try{users.value=(await monitoredUsersApi.list({page:1,page_size:100})).items;tweets.value=(await tweetsApi.list({page:1,page_size:100})).items}catch{}})
</script>

<template><div class="page-stack"><PageHeader eyebrow="CONTENT / 01" title="AI 创作" description="把监听内容转化为可编辑、可发布的创作草稿"><template #actions><a-button @click="loadJobs"><ReloadOutlined /> 刷新任务</a-button></template></PageHeader><a-tabs v-model:activeKey="tab" class="workspace-tabs"><a-tab-pane key="jobs" tab="生成任务"><div class="metric-grid"><MetricCard label="运行中" :value="running" detail="队列 / 执行中" /><MetricCard label="草稿数" :value="jobs.filter((job) => job.draft).length" detail="可继续编辑" accent="sage" /></div><a-card :bordered="false" style="margin-top:18px"><div class="toolbar"><div class="toolbar__controls"><a-select v-model:value="filters.status" style="width:150px" :options="['all','queued','running','succeeded','failed'].map((value)=>({label:value==='all'?'全部状态':value,value}))" @change="loadJobs" /><a-button type="primary" @click="tab='settings'"><ThunderboltOutlined /> 配置 AI</a-button></div><span class="toolbar__hint">共 {{ jobsTotal }} 条任务</span></div><a-table :data-source="jobs" :loading="loading.jobs" row-key="id" :pagination="{current:filters.page,pageSize:filters.page_size,total:jobsTotal,showSizeChanger:false}" @change="(page:any)=>{filters.page=page.current;loadJobs()}"><a-table-column title="源内容"><template #default="{record}"><strong>@{{record.source_username||'未知账号'}}</strong><p class="muted" style="max-width:430px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">{{record.source_text||'—'}}</p></template></a-table-column><a-table-column title="状态"><template #default="{record}"><StatusPill :value="record.status" /></template></a-table-column><a-table-column title="草稿"><template #default="{record}">{{record.draft?.title||'尚未生成'}}</template></a-table-column><a-table-column title="操作"><template #default="{record}"><a-space><a-button v-if="record.draft" type="link" @click="editDraft(record)">编辑草稿</a-button><a-button v-if="record.status==='failed'" type="link" @click="retry(record)">重试</a-button><a-button type="link" danger @click="removeJob(record)"><DeleteOutlined /></a-button></a-space></template></a-table-column></a-table></a-card></a-tab-pane><a-tab-pane key="settings" tab="创作设置"><a-card :bordered="false"><a-form layout="vertical" style="max-width:760px"><a-form-item label="创作开关"><a-switch v-model:checked="settingsForm.enabled" /><span class="muted" style="margin-left:10px">启用后允许创建生成任务</span></a-form-item><a-form-item label="采集后自动生成"><a-switch v-model:checked="settingsForm.auto_generate" :disabled="!settingsForm.enabled" /></a-form-item><a-form-item label="语言与语气"><a-space><a-input v-model:value="settingsForm.language" placeholder="语言" /><a-input v-model:value="settingsForm.tone" placeholder="语气" /></a-space></a-form-item><a-form-item label="默认提示词"><a-textarea v-model:value="settingsForm.prompt_template" :rows="5" /></a-form-item><a-form-item label="推理强度"><a-select v-model:value="settingsForm.reasoning_effort" :options="['none','minimal','low','medium','high','xhigh','max'].map((value)=>({label:value,value}))" style="width:220px" /></a-form-item><a-form-item label="运行参数"><a-space><a-input-number v-model:value="settingsForm.max_attempts" addon-before="重试" :min="1" :max="10" /><a-input-number v-model:value="settingsForm.max_output_tokens" addon-before="Token" :min="128" :max="100000" /><a-input-number v-model:value="settingsForm.request_timeout_seconds" addon-before="超时" :min="10" :max="600" /></a-space></a-form-item><a-button type="primary" :loading="loading.settings" @click="saveSettings"><SaveOutlined /> 保存配置</a-button></a-form></a-card></a-tab-pane><a-tab-pane key="skills" tab="Skills"><a-card :bordered="false"><div class="toolbar"><span class="toolbar__hint">用可复用的提示指令控制输出结构</span><a-button type="primary" @click="editSkill()"><PlusOutlined /> 新建 Skill</a-button></div><a-list :data-source="skills" :loading="loading.skills"><template #renderItem="{item}"><a-list-item><div class="list-row" style="width:100%;padding:10px 0"><div class="list-row__main"><strong>{{item.name}} <a-tag v-if="item.is_active" color="green">启用</a-tag></strong><span>{{item.description||'暂无说明'}}</span></div><a-space><a-button type="link" @click="editSkill(item)"><EditOutlined /></a-button><a-button type="link" danger @click="removeSkill(item)"><DeleteOutlined /></a-button></a-space></div></a-list-item></template></a-list></a-card></a-tab-pane><a-tab-pane key="source" tab="AI 数据源"><a-card :bordered="false"><a-alert type="info" show-icon message="API Key 仅用于后端调用，保存后不会回显。" /><a-form layout="vertical" style="max-width:700px;margin-top:18px"><a-form-item label="名称"><a-input v-model:value="sourceForm.name" /></a-form-item><a-form-item label="Base URL"><a-input v-model:value="sourceForm.base_url" /></a-form-item><a-form-item label="模型"><a-input v-model:value="sourceForm.model" /><div v-if="sourceModels.length" class="muted">可用模型：{{sourceModels.join('、')}}</div></a-form-item><a-form-item label="API Key"><a-input-password v-model:value="sourceForm.api_key" placeholder="首次配置必填" /></a-form-item><a-space><a-button type="primary" :loading="loading.source" @click="saveSource">保存数据源</a-button><a-button :loading="loading.source" @click="testSource">测试连接</a-button></a-space></a-form></a-card></a-tab-pane><a-tab-pane key="context" tab="用户上下文"><a-card :bordered="false"><a-form layout="inline"><a-form-item label="监听账号"><a-select v-model:value="selectedUser" allow-clear style="width:220px" :options="users.map((user)=>({label:`@${user.username}`,value:user.id}))" @change="loadContext" /></a-form-item><a-form-item label="功能点"><a-select v-model:value="feature" style="width:220px" :options="[{label:'文章生成',value:'article_generation'},{label:'内容摘要',value:'content_summary'},{label:'标题优化',value:'title_optimization'}]" @change="loadContext" /></a-form-item></a-form><a-descriptions v-if="profile" bordered :column="1" style="margin-top:20px"><a-descriptions-item label="作者">@{{profile.username}}</a-descriptions-item><a-descriptions-item label="身份">{{profile.identity_summary}}</a-descriptions-item><a-descriptions-item label="近期关注">{{profile.focus_summary}}</a-descriptions-item><a-descriptions-item label="长期主题">{{profile.recurring_topics.join('、')||'暂无'}}</a-descriptions-item></a-descriptions><a-space v-if="binding" direction="vertical" style="width:100%;margin-top:20px"><span class="muted">绑定 Skills</span><a-checkbox-group v-model:value="bindingIds" :options="skills.map((skill) => ({ label: skill.name, value: skill.id }))" /><a-button type="primary" :loading="bindingLoading" @click="saveBinding">保存绑定</a-button></a-space><a-empty v-else description="选择账号后查看画像" /></a-card></a-tab-pane></a-tabs><a-modal v-model:open="skillOpen" :title="editingSkill?'编辑 Skill':'新建 Skill'" ok-text="保存" cancel-text="取消" @ok="saveSkill"><a-form layout="vertical"><a-form-item label="名称"><a-input v-model:value="skillForm.name" /></a-form-item><a-form-item label="说明"><a-input v-model:value="skillForm.description" /></a-form-item><a-form-item label="指令"><a-textarea v-model:value="skillForm.instructions" :rows="10" /></a-form-item><a-form-item label="启用"><a-switch v-model:checked="skillForm.is_active" /></a-form-item></a-form></a-modal><a-modal v-model:open="draftOpen" title="编辑生成草稿" ok-text="保存草稿" cancel-text="取消" width="760px" :confirm-loading="draftSaving" @ok="saveDraft"><a-form layout="vertical"><a-form-item label="标题"><a-input v-model:value="draftForm.title" /></a-form-item><a-form-item label="摘要"><a-textarea v-model:value="draftForm.excerpt" :rows="3" /></a-form-item><a-form-item label="正文"><a-textarea v-model:value="draftForm.content" :rows="14" /></a-form-item></a-form></a-modal></div></template>
